command:
let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag("vagabond-app", "steadyaim"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "steadyaim")) return;

const steadyaim = hero.effects.find(fx => fx.name.toUpperCase() === "STEADY AIM");

if (!steadyaim){
    const effectData = {
      name: `Steady Aim`,
      img: "/icons/skills/targeting/crosshair-pointed-orange.webp",
      showIcon: 2,
      changes: [
        {
          key: "system.modifiers.damage.out.ranged.flatBonus",
          type: "add",
          mode: 2,
          value: 2,
          priority: 20
        }
      ]
    };

    await token.actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
}
else {
  token.actor.deleteEmbeddedDocuments("ActiveEffect", [steadyaim.id]);
}
